class Solution:
    def oddEvenJumps(self, arr):
        n = len(arr)
        good = 0
        for s in range(n):
            cur, odd = s, True
            while True:
                if cur == n - 1:
                    good += 1
                    break
                nxt = -1
                for j in range(cur + 1, n):
                    if odd:
                        if arr[j] >= arr[cur] and (nxt == -1 or arr[j] < arr[nxt]):
                            nxt = j
                    else:
                        if arr[j] <= arr[cur] and (nxt == -1 or arr[j] <= arr[nxt]):
                            nxt = j
                if nxt == -1:
                    break
                cur, odd = nxt, not odd
        return good

