class Solution:
    def oddEvenJumps(self, arr):
        n = len(arr)
        def make_next(order):
            nxt = [-1] * n
            stack = []
            for i in order:
                while stack and stack[-1] < i:
                    nxt[stack.pop()] = i
                stack.append(i)
            return nxt
        idx = sorted(range(n), key=lambda i: (arr[i], i))
        odd_next = make_next(idx)
        idx.sort(key=lambda i: (-arr[i], i))
        even_next = make_next(idx)
        odd = [False] * n
        even = [False] * n
        odd[n - 1] = even[n - 1] = True
        for i in range(n - 2, -1, -1):
            if odd_next[i] != -1:
                odd[i] = even[odd_next[i]]
            if even_next[i] != -1:
                even[i] = odd[even_next[i]]
        return sum(odd)

