class Solution {
public:
    int oddEvenJumps(vector<int>& arr) {
        int n = arr.size();
        vector<int> oddNext(n, -1), evenNext(n, -1);
        vector<int> idx(n);
        iota(idx.begin(), idx.end(), 0);
        auto sweep = [&](vector<int>& nxt) {
            vector<int> st;
            for (int i : idx) {
                while (!st.empty() && st.back() < i) nxt[st.back()] = i, st.pop_back();
                st.push_back(i);
            }
        };
        sort(idx.begin(), idx.end(), [&](int a, int b){ return arr[a] == arr[b] ? a < b : arr[a] < arr[b]; });
        sweep(oddNext);
        sort(idx.begin(), idx.end(), [&](int a, int b){ return arr[a] == arr[b] ? a < b : arr[a] > arr[b]; });
        sweep(evenNext);
        vector<char> odd(n, 0), even(n, 0);
        odd[n-1] = even[n-1] = 1;
        int res = 1;
        for (int i = n - 2; i >= 0; i--) {
            if (oddNext[i] != -1) odd[i] = even[oddNext[i]];
            if (evenNext[i] != -1) even[i] = odd[evenNext[i]];
            res += odd[i];
        }
        return res;
    }
};

