class Solution {
    public int oddEvenJumps(int[] arr) {
        int n = arr.length;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; i++) idx[i] = i;
        int[] oddNext = sweep(arr, idx, true), evenNext = sweep(arr, idx, false);
        boolean[] odd = new boolean[n], even = new boolean[n];
        odd[n - 1] = even[n - 1] = true;
        int res = 1;
        for (int i = n - 2; i >= 0; i--) {
            if (oddNext[i] != -1) odd[i] = even[oddNext[i]];
            if (evenNext[i] != -1) even[i] = odd[evenNext[i]];
            if (odd[i]) res++;
        }
        return res;
    }
    private int[] sweep(int[] arr, Integer[] idx, boolean ascending) {
        int n = arr.length;
        Arrays.sort(idx, (a, b) -> arr[a] == arr[b] ? a - b : (ascending ? arr[a] - arr[b] : arr[b] - arr[a]));
        int[] nxt = new int[n];
        Arrays.fill(nxt, -1);
        Deque<Integer> st = new ArrayDeque<>();
        for (int i : idx) {
            while (!st.isEmpty() && st.peek() < i) nxt[st.pop()] = i;
            st.push(i);
        }
        return nxt;
    }
}

