var oddEvenJumps = function(arr) {
    const n = arr.length;
    const sweep = (cmp) => {
        const idx = [...Array(n).keys()].sort(cmp);
        const nxt = new Array(n).fill(-1);
        const st = [];
        for (const i of idx) {
            while (st.length && st[st.length - 1] < i) nxt[st.pop()] = i;
            st.push(i);
        }
        return nxt;
    };
    const oddNext = sweep((a, b) => arr[a] - arr[b] || a - b);
    const evenNext = sweep((a, b) => arr[b] - arr[a] || a - b);
    const odd = new Array(n).fill(false), even = new Array(n).fill(false);
    odd[n - 1] = even[n - 1] = true;
    let res = 1;
    for (let i = n - 2; i >= 0; i--) {
        if (oddNext[i] !== -1) odd[i] = even[oddNext[i]];
        if (evenNext[i] !== -1) even[i] = odd[evenNext[i]];
        if (odd[i]) res++;
    }
    return res;
};
